using Npgsql;
namespace IcpaaS.Api;
public sealed class CapacityService(PlatformStore store){public async Task Reserve(Guid tenant,Guid call,Guid? process,CancellationToken ct){await using var c=await store.Open(ct);await using var tx=await c.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);await using(var l=new NpgsqlCommand("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",c,tx)){l.Parameters.AddWithValue(tenant.ToString());await l.ExecuteNonQueryAsync(ct);}await using(var clean=new NpgsqlCommand("DELETE FROM capacity_leases WHERE expires_at<now()",c,tx))await clean.ExecuteNonQueryAsync(ct);await using var limits=new NpgsqlCommand("SELECT channel_limit,cps_limit FROM tenant_settings WHERE tenant_id=$1",c,tx);limits.Parameters.AddWithValue(tenant);await using var r=await limits.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new InvalidOperationException("Tenant capacity is not configured");var channels=r.GetInt32(0);var cps=r.GetDecimal(1);await r.CloseAsync();await using var count=new NpgsqlCommand("SELECT count(*),(SELECT count(*) FROM calls WHERE tenant_id=$1 AND created_at>=now()-interval '1 second') FROM capacity_leases WHERE tenant_id=$1",c,tx);count.Parameters.AddWithValue(tenant);await using var cr=await count.ExecuteReaderAsync(ct);await cr.ReadAsync(ct);if(cr.GetInt64(0)>=channels)throw new InvalidOperationException("Tenant channel limit reached");if(cr.GetInt64(1)>=Math.Ceiling(cps))throw new InvalidOperationException("Tenant CPS limit reached");await cr.CloseAsync();await using var add=new NpgsqlCommand("INSERT INTO capacity_leases(tenant_id,process_id,call_id,lease_owner,expires_at) VALUES($1,$2,$3,$4,now()+interval '4 hours')",c,tx);add.Parameters.AddWithValue(tenant);add.Parameters.AddWithValue((object?)process??DBNull.Value);add.Parameters.AddWithValue(call);add.Parameters.AddWithValue(Environment.MachineName);await add.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}public async Task Release(Guid tenant,Guid call,CancellationToken ct){await using var c=await store.Open(ct);await using var q=new NpgsqlCommand("DELETE FROM capacity_leases WHERE tenant_id=$1 AND call_id=$2",c);q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(call);await q.ExecuteNonQueryAsync(ct);}}
